19	func TestSessionExportChangesHTTPSuccess(t *testing.T) {
20		h, _ := newTestHandler(t)
21		createSessionViaHTTP(t, h, "dev", "sess")
22		seedDoc(t, h, "doc1", 3)
23	
24		// from present: the export answers with the changes,count shape — one
25		// compact line, item keys ordered id,deviceId,payload,cursor, exactly one
26		// trailing newline.
27		w, _ := doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?from=0")
28		if w.Code != http.StatusOK {
29			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
30		}
31		if ct := w.Header().Get("Content-Type"); ct != "application/json" {
32			t.Fatalf("content type = %q", ct)
33		}
34		want := `{"changes":[` +
35			`{"id":"c1","deviceId":"dev","payload":{"n":1},"cursor":1},` +
36			`{"id":"c2","deviceId":"dev","payload":{"n":2},"cursor":2},` +
37			`{"id":"c3","deviceId":"dev","payload":{"n":3},"cursor":3}` +
38			`],"count":3}` + "\n"
39		if w.Body.String() != want {
40			t.Fatalf("body = %q\nwant %q", w.Body.String(), want)
41		}
42	
43		// No export parameters at all is still the paged read shape.
44		w, body := doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1"))
45		if w.Code != http.StatusOK {
46			t.Fatalf("paged read status = %d", w.Code)
47		}
48		if body["nextCursor"] == nil || body["count"] != nil {
49			t.Fatalf("paged read shape changed: %s", w.Body.String())
50		}
51	
52		// Closed interval includes both endpoints.
53		w, _ = doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?from=2&to=2")
54		if got := strings.TrimSpace(w.Body.String()); got != `{"changes":[{"id":"c2","deviceId":"dev","payload":{"n":2},"cursor":2}],"count":1}` {
55			t.Fatalf("point body = %q", got)
56		}
57	
58		// Lower bound only (to absent).
59		w, _ = doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?from=3")
60		if got := strings.TrimSpace(w.Body.String()); got != `{"changes":[{"id":"c3","deviceId":"dev","payload":{"n":3},"cursor":3}],"count":1}` {
61			t.Fatalf("from-only body = %q", got)
62		}
63	
64		// to alone applies the lower default of 0.
65		w, _ = doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?to=1")
66		if got := strings.TrimSpace(w.Body.String()); got != `{"changes":[{"id":"c1","deviceId":"dev","payload":{"n":1},"cursor":1}],"count":1}` {
67			t.Fatalf("to-only body = %q", got)
68		}
69	
70		// Explicit empty parameters behave like defaults.
71		w, _ = doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?from=&to=")
72		if w.Code != http.StatusOK || strings.Count(w.Body.String(), `"cursor"`) != 3 {
73			t.Fatalf("empty params = %d %s", w.Code, w.Body.String())
74		}
75	}
