122	func TestSessionExportChangesHTTPCompacted(t *testing.T) {
123		h, _ := newTestHandler(t)
124		createSessionViaHTTP(t, h, "dev-1", "sess")
125		postDocChanges(t, h, "doc", "dev-1", 4)
126		w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 2, "state": map[string]any{"s": 1}})
127		if w.Code != http.StatusOK {
128			t.Fatalf("snapshot = %d %s", w.Code, w.Body.String())
129		}
130		if w := compactChanges(t, h, "doc", "dev-1"); w.Code != http.StatusOK {
131			t.Fatalf("compact = %d %s", w.Code, w.Body.String())
132		}
133	
134		// Unbounded: online tail only.
135		w2, _ := doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc")+"?from=0")
136		want := `{"changes":[` +
137			`{"id":"c3","deviceId":"dev-1","payload":{"n":3},"cursor":3},` +
138			`{"id":"c4","deviceId":"dev-1","payload":{"n":4},"cursor":4}` +
139			`],"count":2}` + "\n"
140		if w2.Body.String() != want {
141			t.Fatalf("tail body = %q\nwant %q", w2.Body.String(), want)
142		}
143	
144		// Interval entirely inside the trimmed region: empty success.
145		w2, _ = doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc")+"?from=0&to=2")
146		if got := w2.Body.String(); got != `{"changes":[],"count":0}`+"\n" {
147			t.Fatalf("trimmed interval body = %q", got)
148		}
149	
150		// Interval straddling the boundary: online rows only.
151		w2, _ = doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc")+"?from=1&to=3")
152		if got := strings.TrimSpace(w2.Body.String()); got != `{"changes":[{"id":"c3","deviceId":"dev-1","payload":{"n":3},"cursor":3}],"count":1}` {
153			t.Fatalf("straddling body = %q", got)
154		}
155	}
