157	func TestSessionExportChangesHTTPMatchesPagedRead(t *testing.T) {
158		h, _ := newTestHandler(t)
159		createSessionViaHTTP(t, h, "dev-a", "sess")
160		postRawChanges(t, h, "doc1", "dev-a", `[
161			{"id":"a1","payload":{"z":1,"a":2}},
162			{"id":"a2","payload":[true,null,0.5]}
163		]`)
164	
165		w, _ := doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?from=0")
166		if w.Code != http.StatusOK {
167			t.Fatalf("export = %d", w.Code)
168		}
169		for cursor, id := range map[int]string{1: "a1", 2: "a2"} {
170			rec, page := doRequest(t, h, http.MethodGet,
171				sessionChangesPath("sess", "doc1")+"?after="+strconv.Itoa(cursor-1)+"&limit=1")
172			if rec.Code != http.StatusOK {
173				t.Fatalf("paged after=%d = %d", cursor-1, rec.Code)
174			}
175			rows := page["changes"].([]any)
176			if len(rows) != 1 {
177				t.Fatalf("paged rows = %v", rows)
178			}
179			paged := rows[0].(map[string]any)
180			export := w.Body.String()
181			needle := `"id":"` + id + `"`
182			if !strings.Contains(export, needle) {
183				t.Fatalf("export missing %s: %s", id, export)
184			}
185			if paged["id"] != id || int(paged["cursor"].(float64)) != cursor {
186				t.Fatalf("paged row mismatch: %+v", paged)
187			}
188		}
189	}
