191	func TestSessionExportChangesHTTPRejectsBadQuery(t *testing.T) {
192		h, _ := newTestHandler(t)
193		createSessionViaHTTP(t, h, "dev", "sess")
194		seedDoc(t, h, "doc1", 1)
195	
196		for _, q := range []string{
197			"from=x",
198			"from=-1",
199			"from=1.5",
200			"from=1e3",
201			"from=+1",
202			"to=x",
203			"to=-1",
204			"to=1.5",
205			"from=3&to=2",
206			"from=99999999999999999999",
207			"to=99999999999999999999",
208		} {
209			w, _ := doRequest(t, h, http.MethodGet, sessionChangesPath("sess", "doc1")+"?"+q)
210			if w.Code != http.StatusBadRequest {
211				t.Fatalf("?%s status = %d, want 400, body = %s", q, w.Code, w.Body.String())
212			}
213			if ct := w.Header().Get("Content-Type"); ct != "application/json" {
214				t.Fatalf("?%s content type = %q", q, ct)
215			}
216			if !strings.Contains(w.Body.String(), `"error"`) {
217				t.Fatalf("?%s body = %s", q, w.Body.String())
218			}
219		}
220	
221		// Shape errors take precedence over the session lookup: an illegal
222		// interval against a never-created session is still a 400.
223		w, body := doRequest(t, h, http.MethodGet, sessionChangesPath("ghost", "doc1")+"?from=x")
224		if w.Code != http.StatusBadRequest || body["error"] == nil {
225			t.Fatalf("bad param + missing session = %d %v", w.Code, body)
226		}
227	
228		// Empty identifiers are a 400 JSON error, not a redirect.
229		for _, p := range []string{
230			"/v1/sessions//documents/doc1/changes?from=0",
231			"/v1/sessions/sess/documents//changes?from=0",
232		} {
233			w, _ := doRequest(t, h, http.MethodGet, p)
234			if w.Code != http.StatusBadRequest {
235				t.Fatalf("%s status = %d, want 400", p, w.Code)
236			}
237			assertJSONError(t, w)
238		}
239	
240		// Zero writes: the rejected requests moved the change cursor nowhere.
241		_, list := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/changes")
242		if list["nextCursor"].(float64) != 1 {
243			t.Fatalf("nextCursor = %v", list["nextCursor"])
244		}
245	}
