272	func TestSessionExportChangesHTTPPermissionRevoked(t *testing.T) {
273		h, _ := newTestHandler(t)
274		createSessionViaHTTP(t, h, "dev-1", "sess")
275		seedDoc(t, h, "doc1", 2)
