241		if before["nextCursor"].(float64) != 2 {
242			t.Fatalf("seed nextCursor = %v", before["nextCursor"])
243		}
244	
245		// Repeated exports change nothing.
246		for i := 0; i < 3; i++ {
247			w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots")
248			if w.Code != http.StatusOK {
249				t.Fatalf("export %d = %d", i, w.Code)
250			}
251		}
252	
253		_, after := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/changes")
254		if after["nextCursor"].(float64) != 2 {
255			t.Fatalf("nextCursor moved to %v after exports", after["nextCursor"])
256		}
257		// The snapshot set still contains exactly the two seeded snapshots.
258		w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots")
259		if strings.Count(w.Body.String(), `"cursor"`) != 2 {
260			t.Fatalf("snapshot set changed after exports: %s", w.Body.String())
261		}
