263	
264	func TestExportSnapshotsHTTPPersistenceAcrossRestart(t *testing.T) {
265		path := filepath.Join(t.TempDir(), "export-http.db")
266	
267		s, err := app.Open(path)
268		if err != nil {
269			t.Fatal(err)
270		}
271		h := NewHandler(s)
272		seedSnapshots(t, h, "doc1", map[int]string{1: `{"a":1}`, 2: `[1,2]`, 3: `null`})
273		w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots?from=1&to=3")
274		if w.Code != http.StatusOK {
275			t.Fatalf("export before restart = %d", w.Code)
276		}
277		before := w.Body.Bytes()
278		if err := s.Close(); err != nil {
279			t.Fatal(err)
280		}
281	
282		s2, err := app.Open(path)
283		if err != nil {
284			t.Fatal(err)
285		}
286		t.Cleanup(func() { _ = s2.Close() })
287		h2 := NewHandler(s2)
288	
289		w2, _ := doRequest(t, h2, http.MethodGet, "/v1/documents/doc1/snapshots?from=1&to=3")
290		if w2.Code != http.StatusOK {
291			t.Fatalf("export after restart = %d", w2.Code)
292		}
293		if string(w2.Body.Bytes()) != string(before) {
294			t.Fatalf("export body changed across restart:\nbefore %q\nafter  %q", before, w2.Body.Bytes())
295		}
296	}
