604	func TestSnapshotRetryAndConflictHTTP(t *testing.T) {
605		h, _ := newTestHandler(t)
606		seedDoc(t, h, "doc1", 1)
607	
608		w, body := postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":1}}`)
609		if w.Code != http.StatusOK || body["created"] != true {
610			t.Fatalf("first = %d %v", w.Code, body)
611		}
612	
613		// Decoded-equal retry (different key order and number format) is idempotent.
614		w, body = postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":1.0}}`)
615		if w.Code != http.StatusOK || body["created"] != false {
