617		}
618	
619		// A different state is a 409 and leaves the snapshot unchanged.
620		w, _ = postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":2}}`)
621		if w.Code != http.StatusConflict {
622			t.Fatalf("conflict status = %d", w.Code)
623		}
624		var errBody map[string]string
625		if err := json.Unmarshal(w.Body.Bytes(), &errBody); err != nil || errBody["error"] == "" {
626			t.Fatalf("conflict body = %s", w.Body.String())
627		}
628		_, body = doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots/1")
629		if body["state"].(map[string]any)["v"].(float64) != 1 {
630			t.Fatalf("state after conflict = %v", body["state"])
631		}
632	}
