func TestRestoreHTTPSuccess(t *testing.T) {
	h, _ := newTestHandler(t)
	seedSnapshot(t, h, "doc1", 2, `{"text":"hello","n":1}`)

	w, body := restoreJSON(t, h, "doc1", map[string]any{
		"deviceId":       "dev-A",
