	var wg sync.WaitGroup
	errs := make(chan error, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			w, _ := restoreJSON(t, h, "doc1", map[string]any{
				"deviceId": "dev", "changeId": fmt.Sprintf("r%02d", i), "snapshotCursor": 1,
