	snaps, err := s.ExportSnapshots(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export snapshots")
		return
	}
	writeSnapshotExport(w, snapshotExportItems(snaps))
}

