package server

import (
	"net/http"
	"path/filepath"
	"strings"
	"testing"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
)

// sessionSnapshotsPath is the session-scoped snapshot collection path; the
// interval export is its only read shape.
func sessionSnapshotsPath(session, doc string) string {
	return "/v1/sessions/" + session + "/documents/" + doc + "/snapshots"
}

func TestSessionExportSnapshotsHTTPSuccess(t *testing.T) {
	h, _ := newTestHandler(t)
	createSessionViaHTTP(t, h, "dev", "sess")
	seedSnapshots(t, h, "doc1", map[int]string{
		1: "null",
		2: `42`,
		3: `"str"`,
		4: `[1,2]`,
		5: `{"a":1}`,
	})

	// from present: the export answers with the snapshots,count shape — one
	// compact line, item keys ordered cursor,state, exactly one trailing
	// newline, byte-for-byte the document-level export's body.
	w, _ := doRequest(t, h, http.MethodGet, sessionSnapshotsPath("sess", "doc1")+"?from=0")
	if w.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
	}
	if ct := w.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("content type = %q", ct)
	}
	docLevel, _ := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots?from=0")
	if w.Body.String() != docLevel.Body.String() {
		t.Fatalf("session body %q != document body %q", w.Body.String(), docLevel.Body.String())
