	for i := 0; i < 3; i++ {
		w, _ := doRequest(t, h, http.MethodGet, sessionSnapshotsPath("sess", "doc1")+"?from=0")
		if w.Code != http.StatusOK {
			t.Fatalf("export %d = %d", i, w.Code)
		}
	}

	// Exports move the change cursor nowhere.
	_, after := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/changes")
	if after["nextCursor"].(float64) != 2 {
		t.Fatalf("nextCursor moved to %v after exports", after["nextCursor"])
	}
	// The snapshot set is unchanged and the document-level export agrees.
	session, _ := doRequest(t, h, http.MethodGet, sessionSnapshotsPath("sess", "doc1")+"?from=0")
	document, _ := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots")
	if strings.Count(session.Body.String(), `"cursor"`) != 2 {
		t.Fatalf("snapshot set changed after exports: %s", session.Body.String())
